import app from 'flarum/admin/app';
import Admin from 'flarum/common/extenders/Admin';
import Group from 'flarum/common/models/Group';
import LadderEditor from './components/LadderEditor';
import state from './state';
const key = name => `ernestdefoe-ladder.${name}`;
const t = function (name, params) {
  if (params === void 0) {
    params = {};
  }
  return app.translator.trans(`ernestdefoe-ladder.admin.${name}`, params);
};

/*
 * 🚨 The `Admin` extender, NOT `app.extensionData`: that is Flarum 1.x and
 * absent in Flarum 2.
 *
 * The ladder itself saves as you edit it, through its own API. The three
 * settings below are ordinary settings and go out with the page's Save button.
 */
export default [new Admin().customSetting(() => m(LadderEditor, null)).setting(() => ({
  setting: key('inherit_permissions'),
  type: 'switch',
  label: t('settings.inherit_label'),
  help: t('settings.inherit_help')
})).setting(() => ({
  setting: key('demote'),
  type: 'switch',
  label: t('settings.demote_label'),
  help: t('settings.demote_help')
})).customSetting(function () {
  const stream = this.setting(key('exempt_groups'), '[]');
  let selected = [];
  try {
    selected = JSON.parse(stream() || '[]').map(Number);
  } catch (e) {
    selected = [];
  }
  const rungGroups = (state.ladder?.rungs ?? []).map(rung => String(rung.groupId));
  const groups = app.store.all('groups').filter(group => group.id() !== Group.GUEST_ID && group.id() !== Group.MEMBER_ID && !rungGroups.includes(group.id()));
  const toggle = (id, on) => {
    const next = on ? [...new Set([...selected, id])] : selected.filter(existing => existing !== id);
    stream(JSON.stringify(next));
  };
  return m("div", {
    className: "Form-group LadderExempt"
  }, m("label", null, t('settings.exempt_label')), m("div", {
    className: "helpText"
  }, t('settings.exempt_help')), m("div", {
    className: "LadderExempt-list"
  }, groups.map(group => {
    const id = Number(group.id());
    return m("label", {
      className: "checkbox LadderExempt-item"
    }, m("input", {
      type: "checkbox",
      checked: selected.includes(id),
      onchange: e => toggle(id, e.target.checked)
    }), group.namePlural());
  })));
}).setting(() => ({
  setting: key('show_nav'),
  type: 'switch',
  label: t('settings.show_nav_label'),
  help: t('settings.show_nav_help')
}))];